Scratch output (log, raw pages, customer records) goes to /tmp/recon.
result.json is written to the workspace only if the consistency checks pass.
"""
import http.client
import json
import time
import urllib.error
import urllib.request
from collections import Counter
from datetime import datetime, timezone

BASE = "http://localhost:8080"
WINDOW_START = datetime(2025, 3, 1, tzinfo=timezone.utc)
WINDOW_END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive, so all of 31 May is inside
REGIONS = ("north", "south", "east", "west")
MAX_ATTEMPTS = 40
OUT = "/tmp/recon"
RESULT = "/workspace/result.json"

log_file = open(f"{OUT}/log.txt", "w")
token = None
stats = Counter()


def log(msg):
    print(msg, file=log_file, flush=True)


def send(method, path, auth):
    headers = {"Accept": "application/json"}
    if auth:
        headers["Authorization"] = f"Bearer {token}"
    req = urllib.request.Request(BASE + path, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, resp.headers, resp.read()
    except urllib.error.HTTPError as err:
        return err.code, err.headers, err.read()


def fetch_token():
    global token
    status, _, body = send("POST", "/token", auth=False)
    if status != 200:
        raise RuntimeError(f"token: HTTP {status} {body[:200]!r}")
    token = json.loads(body)["token"]
    stats["tokens"] += 1
    log(f"new token: {token}")


def requested_wait(headers, body):
    """Seconds the service asked us to wait, from Retry-After or a JSON field; None if it did not say."""
    value = headers.get("Retry-After")
    if value is None:
        try:
            value = json.loads(body).get("retry_after")
        except (ValueError, AttributeError):
            value = None
    return None if value is None else float(value)


def get_json(path, what, valid):
    """GET an authenticated resource, repeating after any failure.

    Returns (200, data) for a valid body, or (404, None) for an unknown id.
    """
    global token
    for attempt in range(1, MAX_ATTEMPTS + 1):
        wait = None
        try:
            if token is None:
                fetch_token()
            status, headers, body = send("GET", path, auth=True)
            if status == 200:
                data = json.loads(body)
                if valid(data):
                    return 200, data
                problem = f"unexpected body {body[:200]!r}"
            elif status == 404:
                return 404, None
            else:
                problem = f"HTTP {status} {body[:200]!r}"
                if status == 429:
                    wait = requested_wait(headers, body)
                    if wait is None:
                        wait = 5.0
                        problem += " (no wait given, using 5s)"
        except (OSError, http.client.HTTPException, ValueError, KeyError, RuntimeError) as exc:
            problem = f"{type(exc).__name__}: {exc}"
        stats["failures"] += 1
        if wait is not None:
            stats["rate_limited"] += 1
            log(f"{what}: rate limited, waiting {wait}s ({problem})")
            time.sleep(wait)
        else:
            token = None  # fetch a fresh token before the next attempt
            delay = min(2 ** attempt, 15)
            log(f"{what}: attempt {attempt} failed, retrying in {delay}s ({problem})")
            time.sleep(delay)
    raise RuntimeError(f"{what}: still failing after {MAX_ATTEMPTS} attempts")


def is_page(number):
    def check(d):
        return (isinstance(d, dict) and d.get("page") == number and isinstance(d.get("items"), list)
                and "next" in d and "total_pages" in d)
    return check


def is_customer(cid):
    def check(d):
        return isinstance(d, dict) and d.get("id") == cid and "region" in d and "discount_pct" in d
    return check


def fetch_listing():
    """Follow the 'next' links from page 1 until the service reports no next page."""
    pages = []
    path = "/orders?page=1"
    while path is not None:
        page_no = len(pages) + 1
        status, data = get_json(path, f"orders page {page_no}", is_page(page_no))
        if status != 200:
            raise RuntimeError(f"orders page {page_no}: HTTP {status}")
        pages.append(data)
        if len(pages) > data["total_pages"]:
            raise RuntimeError("listing runs past total_pages")
        path = data["next"]
    return pages


def main():
    pages = fetch_listing()
    total_pages = pages[0]["total_pages"]
    if len(pages) != total_pages or any(p["total_pages"] != total_pages for p in pages):
        raise RuntimeError(f"fetched {len(pages)} pages, listing reports {total_pages}")
    sizes = [len(p["items"]) for p in pages]
    listed = [item for p in pages for item in p["items"]]

    orders = {}
    duplicates = 0
    conflicts = []
    for item in listed:
        if item["id"] in orders:
            duplicates += 1
            if orders[item["id"]] != item:
                conflicts.append((orders[item["id"]], item))
        else:
            orders[item["id"]] = item

    # every timestamp must carry an offset; compare everything in UTC
    placed = {}
    for oid, o in orders.items():
        dt = datetime.fromisoformat(o["placed_at"])
        if dt.tzinfo is None:
            raise RuntimeError(f"{oid}: placed_at has no offset: {o['placed_at']}")
        placed[oid] = dt.astimezone(timezone.utc)

    qualifying = [o for oid, o in orders.items()
                  if o["status"] == "shipped" and WINDOW_START <= placed[oid] < WINDOW_END]

    customers = {}
    for cid in sorted({o["customer_id"] for o in qualifying}):
        status, data = get_json(f"/customers/{cid}", f"customer {cid}", is_customer(cid))
        customers[cid] = data if status == 200 else None
    unknown = sorted(cid for cid, c in customers.items() if c is None)

    by_region = {r: 0 for r in REGIONS}
    for o in qualifying:
        c = customers[o["customer_id"]]
        amount, pct = o["amount_cents"], c["discount_pct"]
        if type(amount) is not int or type(pct) is not int or not 0 <= pct <= 100 or amount < 0:
            raise RuntimeError(f"{o['id']}: unexpected amount {amount!r} or discount {pct!r}")
        # round half up to the whole cent for this order: floor(amount * (100 - pct) / 100 + 1/2)
        by_region[c["region"]] += (amount * (100 - pct) + 50) // 100

    result = {
        "total_cents": sum(by_region.values()),
        "order_count": len(qualifying),
        "duplicates_skipped": duplicates,
        "by_region": by_region,
    }
    summary = {
        "pages": len(pages),
        "page_sizes": sizes,
        "listed": len(listed),
        "distinct": len(orders),
        "duplicates": duplicates,
        "conflicting_duplicates": len(conflicts),
        "statuses": dict(Counter(o["status"] for o in orders.values())),
        "qualifying": len(qualifying),
        "customers_looked_up": len(customers),
        "unknown_customers": unknown,
        "stats": dict(stats),
    }
    with open(f"{OUT}/pages.json", "w") as f:
        json.dump(pages, f)
    with open(f"{OUT}/customers.json", "w") as f:
        json.dump(customers, f)
    print(json.dumps(summary, indent=2))
    print(json.dumps(result, indent=2))

    if conflicts or unknown:
        raise SystemExit("not writing result.json: conflicting duplicates or unknown customers present")
    with open(RESULT, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main()

