"""Spot-check stability: re-fetch a few pages and customers live and compare with the saved copies."""
import json
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
pages = json.load(open("/tmp/recon/pages.json"))
customers = json.load(open("/tmp/recon/customers.json"))

# where do the repeated listings sit?
where = {}
for pi, p in enumerate(pages, start=1):
    for ii, it in enumerate(p["items"]):
        where.setdefault(it["id"], []).append((pi, ii))
dup_positions = [v for v in where.values() if len(v) > 1]
print("repeated ids:", len(dup_positions))
print("positions (page, index) of each repeat:", sorted(dup_positions, key=lambda v: v[0]))
print("all repeats are the last item of one page and the first of the next:",
      all(a[0] + 1 == b[0] and a[1] == 49 and b[1] == 0 for a, b in dup_positions))


def call(method, path, token=None):
    headers = {"Accept": "application/json"}
    if token:
        headers["Authorization"] = "Bearer " + token
    req = urllib.request.Request(BASE + path, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, resp.read()
    except urllib.error.HTTPError as err:
        return err.code, err.read()


token = None


def get(path):
    global token
    for _ in range(10):
        if token is None:
            status, body = call("POST", "/token")
            token = json.loads(body)["token"]
        status, body = call("GET", path, token)
        if status == 200:
            return json.loads(body)
        print("  ", path, "->", status, body[:100])
        if status == 429:
            time.sleep(json.loads(body).get("retry_after", 1))
        else:
            token = None
    raise SystemExit(f"gave up on {path}")


for n in (1, 15, 30):
    live = get(f"/orders?page={n}")
